import { request, requestOrNull, seg, Page, requestFile, ExportRequest, ApiError } from './apiSupport';
import { MemberDTO } from './MemberDTO';
import { MemberKeyDTO } from './MemberKeyDTO';
import { MemberSrchDTO } from './MemberSrchDTO';

/**
 * REST client for Member.
 *
 * Calls the endpoints MemberController exposes. Generated from the same model the
 * server is, so a change to the DSL shows up here as a type error rather than
 * at runtime.
 *
 * Generated by ElastiCORE. Do not edit outside the ElastiCORE guidelines.
 */
const BASE = '/api/crm/member';

/** Registers a new Member. */
export async function create(input: MemberDTO, init?: RequestInit): Promise<MemberDTO> {
    return request<MemberDTO>('POST', BASE, input, init);
}

/** The Member with this identifier, or null when there is none. */
export async function findById(memberId: number, init?: RequestInit): Promise<MemberDTO | null> {
    return requestOrNull<MemberDTO>('GET', BASE + '/' + seg(memberId), init);
}

/** Every Member matching the condition. */
export async function search(condition: MemberSrchDTO, init?: RequestInit): Promise<Page<MemberDTO>> {
    return request<Page<MemberDTO>>('POST', BASE + '/search', condition, init);
}

/** Updates an existing Member. */
export async function update(input: MemberDTO, init?: RequestInit): Promise<MemberDTO> {
    return request<MemberDTO>('PUT', BASE, input, init);
}

/** Updates several in one transaction; none are applied if any fails. */
export async function batchUpdate(inputs: MemberDTO[], init?: RequestInit): Promise<void> {
    return request<void>('PUT', BASE + '/batch', inputs, init);
}

/** Deletes each key, answering for each whether it was there. */
export async function deleteMany(keys: MemberKeyDTO[], init?: RequestInit): Promise<boolean[]> {
    return request<boolean[]>('POST', BASE + '/delete', keys, init);
}

/** Deletes the Member with this identifier. */
export async function deleteById(memberId: number, init?: RequestInit): Promise<boolean> {
    return request<boolean>('DELETE', BASE + '/' + seg(memberId), undefined, init);
}

/** The rows the search finds as a file: CSV, or an .xlsx workbook (format: 'xlsx'). */
export async function exportMember(body: ExportRequest<MemberSrchDTO>, init?: RequestInit): Promise<Blob> {
    return requestFile('POST', BASE + '/export', body, init);
}

/** Signs in: the session cookie is set (same origin) and the Member answered; ApiError 401 when the login or the password is wrong. */
export async function signIn(login: string, password: string, init?: RequestInit): Promise<MemberDTO> {
    return request<MemberDTO>('POST', BASE + '/signin', { login, password }, init);
}

/** Signs out: the session ends. */
export async function signOut(init?: RequestInit): Promise<void> {
    return request<void>('POST', BASE + '/signout', undefined, init);
}

/** The Member signed in now, or null for a visitor. */
export async function me(init?: RequestInit): Promise<MemberDTO | null> {
    try {
        return await request<MemberDTO>('GET', BASE + '/me', undefined, init);
    } catch (e) {
        if (e instanceof ApiError && e.status === 401) return null;
        throw e;
    }
}

